#!/usr/bin/env python3
"""Day 001: Architecture trade-off inventory (study starter)."""
from __future__ import annotations

import argparse
import json

DEFAULT_STACK = {
"api": {"purpose": "request handling", "cost_ops": 2, "user_impact_if_removed": "total outage"},
"postgres": {"purpose": "system of record", "cost_ops": 4, "user_impact_if_removed": "data loss risk"},
"redis_cache": {"purpose": "hot read acceleration", "cost_ops": 3, "user_impact_if_removed": "slow pages"},
"queue": {"purpose": "async work", "cost_ops": 3, "user_impact_if_removed": "stale side effects"},
"search_index": {"purpose": "full-text search", "cost_ops": 4, "user_impact_if_removed": "search broken"},
}

IMPACT_ORDER = {"total outage": 0, "data loss risk": 1, "search broken": 2, "slow pages": 3, "stale side effects": 4}


def inventory(stack: dict) -> list[dict]:
rows = []
for name, meta in stack.items():
rows.append({"component": name, **meta, "ops_score": meta["cost_ops"]})
rows.sort(key=lambda r: (-r["ops_score"], r["component"]))
return rows


def simulate_removal(stack: dict, component: str) -> dict:
if component not in stack:
raise SystemExit(f"Unknown component: {component}")
remaining = {k: v for k, v in stack.items() if k != component}
impact = stack[component]["user_impact_if_removed"]
return {"removed": component, "first_user_pain": impact, "remaining_components": list(remaining)}


def main() -> None:
p = argparse.ArgumentParser(description="Architecture trade-off inventory")
p.add_argument("--break", dest="break_component", metavar="NAME", help="Simulate removing a component")
p.add_argument("--json", action="store_true", help="Emit JSON")
args = p.parse_args()

rows = inventory(DEFAULT_STACK)
if args.break_component:
result = simulate_removal(DEFAULT_STACK, args.break_component)
payload = {"inventory": rows, "removal_simulation": result}
else:
payload = {"inventory": rows, "hint": "Try --break redis_cache"}

if args.json:
print(json.dumps(payload, indent=2))
else:
print("=== Architecture inventory (higher ops_score = more operational cost) ===")
for r in rows:
print(f" {r['component']:14} ops={r['ops_score']} purpose={r['purpose']}")
if args.break_component:
sim = payload["removal_simulation"]
print(f"\nRemoved {sim['removed']!r} -> first user pain: {sim['first_user_pain']}")
else:
print("\nRun with --break <component> to simulate removal.")


if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 003: System of record vs derived lineage."""
from __future__ import annotations

import argparse
import json
import time

LINEAGE = {
"postgres": {"role": "system_of_record", "rebuildable": False, "rebuild_sec": None},
"redis_cache": {"role": "derived", "rebuildable": True, "rebuild_sec": 120},
"search_index": {"role": "derived", "rebuildable": True, "rebuild_sec": 900},
"analytics_warehouse": {"role": "derived", "rebuildable": True, "rebuild_sec": 3600},
}


def rebuild(name: str, meta: dict) -> dict:
if not meta["rebuildable"]:
return {"store": name, "status": "CANNOT_REBUILD", "note": "source of truth lost"}
time.sleep(0.01)
return {"store": name, "status": "rebuilt", "seconds": meta["rebuild_sec"]}


def main() -> None:
p = argparse.ArgumentParser(description="Data lineage and rebuild simulation")
p.add_argument("--break", dest="break_store", metavar="NAME", help="Simulate corrupting a derived store")
p.add_argument("--json", action="store_true")
args = p.parse_args()

print("=== Data lineage ===")
for name, meta in LINEAGE.items():
rb = "yes" if meta["rebuildable"] else "NO"
print(f" {name:22} role={meta['role']:18} rebuildable={rb}")

if args.break_store:
if args.break_store not in LINEAGE:
raise SystemExit(f"Unknown store: {args.break_store}")
meta = LINEAGE[args.break_store]
print(f"\n--break: corrupting {args.break_store!r}")
result = rebuild(args.break_store, meta)
if args.json:
print(json.dumps(result, indent=2))
else:
print(f" outcome: {result['status']}")
if result.get("seconds"):
print(f" rebuild_time_sec~={result['seconds']} staleness until users notice")
else:
print("\nTry --break search_index or --break postgres")


if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 004: Cloud vs self-hosted ADR scorer."""
from __future__ import annotations

import argparse

OPTIONS = {
"managed": {"monthly_usd": 1200, "rto_hr": 1, "rpo_min": 5, "ops_hr_week": 2, "owner": "vendor"},
"self_hosted": {"monthly_usd": 400, "rto_hr": 4, "rpo_min": 15, "ops_hr_week": 12, "owner": "your_team"},
}


def score(opt: dict, break_region: bool) -> dict:
s = dict(opt)
if break_region:
s["rto_hr"] *= 2 if opt["owner"] == "your_team" else 1.5
s["note"] = "region outage: recovery owner differs"
return s


def main() -> None:
p = argparse.ArgumentParser(description="Compare managed vs self-hosted Postgres ADR")
p.add_argument("--break", dest="break_mode", action="store_true", help="Simulate region outage")
args = p.parse_args()

print("=== Postgres hosting ADR (sample numbers) ===")
for name, opt in OPTIONS.items():
row = score(opt, args.break_mode)
print(f" {name:12} $/mo={row['monthly_usd']:4} RTO={row['rto_hr']}h RPO={row['rpo_min']}m ops={row['ops_hr_week']}h/wk paged={row['owner']}")
if args.break_mode:
print("\n--break: region outage - managed=vendor ticket, self=your on-call")


if __name__ == "__main__":
main()

