#!/usr/bin/env python3
"""Day 009: Fault tree availability estimate."""
from __future__ import annotations
import argparse

LEAVES = {"db": 0.999, "payments": 0.999, "auth": 0.999, "cdn": 0.995}

def series(avail: list[float]) -> float:
p = 1.0
for a in avail:
p *= a
return p

def main() -> None:
p = argparse.ArgumentParser(description="Fault tree availability")
p.add_argument("--break", dest="break_mode", action="store_true", help="Correlate failures: shared region")
args = p.parse_args()
vals = list(LEAVES.values())
indep = series(vals)
print("=== Leaf availability ===")
for name, a in LEAVES.items():
print(f" {name}: {a:.3%}")
print(f"\n system (independent series): {indep:.3%} (~{(1-indep)*525600:.0f} min/yr down)")
if args.break_mode:
corr = min(vals) # all fail together
print(f" system (correlated/shared region): {corr:.3%}")
print("\n--break: correlated failures erase independence gains")

if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 011: Scale-out efficiency simulator."""
from __future__ import annotations
import argparse

def throughput(workers: int, shared: bool) -> float:
per = 100.0
if shared:
return per # serialized on shared lock
return per * workers * 0.9 # 90% parallel efficiency

def main() -> None:
p = argparse.ArgumentParser(description="Scale-out experiment")
p.add_argument("--break", dest="break_mode", action="store_true", help="Enable shared lock bottleneck")
args = p.parse_args()
print("=== Throughput vs workers ===")
for w in [1, 2, 4, 8]:
tp = throughput(w, args.break_mode)
eff = tp / w
print(f" workers={w} throughput={tp:.0f}/s efficiency={eff:.0%}")
if args.break_mode:
print("\n--break: shared lock -> scaling plateaus at ~100/s")

if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 016: Evolvability deploy order matrix."""
from __future__ import annotations
import argparse

def compatible(client_new: bool, server_new: bool, order: str) -> bool:
if order == "consumers_first":
return not (client_new and not server_new)
return not (server_new and not client_new)

def main() -> None:
p = argparse.ArgumentParser(description="Deploy order compatibility")
p.add_argument("--order", choices=["consumers_first", "producers_first"], default="consumers_first")
p.add_argument("--break", dest="break_mode", action="store_true", help="Deploy in wrong order")
args = p.parse_args()
order = "producers_first" if args.break_mode else args.order
print(f"deploy order: {order}")
cases = [(False, False), (False, True), (True, False), (True, True)]
for c, s in cases:
ok = compatible(c, s, order)
print(f" client_new={c} server_new={s} -> {'OK' if ok else 'BREAK'}")
if args.break_mode:
print("\n--break: producers_first with new server/old client breaks reads")

if __name__ == "__main__":
main()

