"""Day 017: Relational schema with constraints (sqlite)."""
from __future__ import annotations
import argparse, sqlite3

DDL = '''
CREATE TABLE customers (id INTEGER PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE orders (id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES customers(id));
CREATE TABLE line_items (id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id), qty INTEGER NOT NULL CHECK(qty > 0));
'''

def main() -> None:
p = argparse.ArgumentParser(description="Relational constraints lab")
p.add_argument("--break", dest="break_mode", action="store_true", help="Try orphan line item insert")
args = p.parse_args()
con = sqlite3.connect(":memory:")
con.executescript(DDL)
con.execute("INSERT INTO customers VALUES (1, 'Ada')")
con.execute("INSERT INTO orders VALUES (1, 1)")
con.execute("INSERT INTO line_items VALUES (1, 1, 2)")
print("valid inserts: OK")
tests = [("orphan line item", "INSERT INTO line_items VALUES (2, 99, 1)"), ("negative qty", "INSERT INTO line_items VALUES (3, 1, -1)")]
if not args.break_mode:
tests = tests[:1]
for label, sql in tests:
try:
con.execute(sql)
con.commit()
print(f" {label}: UNEXPECTED OK")
except sqlite3.IntegrityError as e:
print(f" {label}: blocked ({e})")

if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 018: Document modeling with SQLite JSON."""
from __future__ import annotations
import argparse, json, sqlite3, time

def main() -> None:
p = argparse.ArgumentParser(description="Document modeling lab")
p.add_argument("--orders", type=int, default=1000)
p.add_argument("--break", dest="break_mode", action="store_true", help="Update one sku across all orders")
args = p.parse_args()
con = sqlite3.connect(":memory:")
con.execute("CREATE TABLE orders (id INTEGER PRIMARY KEY, doc TEXT NOT NULL)")
sku = "WIDGET-A"
for i in range(args.orders):
doc = {"id": i, "items": [{"sku": sku, "qty": 1}]}
con.execute("INSERT INTO orders VALUES (?, ?)", (i, json.dumps(doc)))
t0 = time.perf_counter()
if args.break_mode:
rows = con.execute("SELECT id, doc FROM orders").fetchall()
for oid, raw in rows:
d = json.loads(raw)
for it in d["items"]:
if it["sku"] == sku:
it["sku"] = "WIDGET-B"
con.execute("UPDATE orders SET doc=? WHERE id=?", (json.dumps(d), oid))
con.commit()
else:
row = con.execute("SELECT doc FROM orders WHERE id=0").fetchone()
print(f"single read: {json.loads(row[0])}")
ms = (time.perf_counter() - t0) * 1000
print(f"orders={args.orders} ms={ms:.1f}")
if args.break_mode:
print("\n--break: partial update scanned all docs - boundary signal")

if __name__ == "__main__":
main()

#!/usr/bin/env python3
"""Day 019: Normalized vs denormalized benchmark."""
from __future__ import annotations
import argparse, sqlite3, time

def bench(con: sqlite3.Connection, sql: str, n: int = 100) -> float:
t0 = time.perf_counter()
for _ in range(n):
con.execute(sql).fetchone()
return (time.perf_counter() - t0) * 1000

def main() -> None:
p = argparse.ArgumentParser(description="Norm vs denorm benchmark")
p.add_argument("--break", dest="break_mode", action="store_true", help="Skip denorm update -> drift")
args = p.parse_args()
con = sqlite3.connect(":memory:")
con.executescript('''
CREATE TABLE orders (id INT PRIMARY KEY, customer_id INT, total REAL);
CREATE TABLE denorm_summary (order_id INT PRIMARY KEY, summary TEXT);
INSERT INTO orders VALUES (1,1,10.0);
INSERT INTO denorm_summary VALUES (1, 'cust=1 total=10');
''')
read_norm = bench(con, "SELECT o.id, o.total FROM orders o WHERE o.id=1")
read_denorm = bench(con, "SELECT summary FROM denorm_summary WHERE order_id=1")
con.execute("UPDATE orders SET total=20 WHERE id=1")
if not args.break_mode:
con.execute("UPDATE denorm_summary SET summary='cust=1 total=20' WHERE order_id=1")
den = con.execute("SELECT summary FROM denorm_summary").fetchone()[0]
print(f"read_ms norm={read_norm:.2f} denorm={read_denorm:.2f}")
print(f" denorm_summary after write: {den!r}")
if args.break_mode:
print("\n--break: forgot denorm update -> stale summary visible")

if __name__ == "__main__":
main()

