p.add_argument("--break", dest="break_query", metavar="QUERY", help="Add adversarial access pattern")
args = p.parse_args()
qs = list(QUERIES)
if args.break_query:
qs.append(("live_recommendations", "graph", {"relational": 1, "document": 2, "graph": 5}))
